import os
fd = os.open('images/rootfs.img', os.O_RDONLY)
size = os.path.getsize('images/rootfs.img')
print(f"apparent size: {size}")
pos = 0
extents = []
while pos < size:
    try:
        data = os.lseek(fd, pos, os.SEEK_DATA)
    except OSError:
        break
    hole = os.lseek(fd, data, os.SEEK_HOLE)
    extents.append((data, hole))
    pos = hole
for i, (s, e) in enumerate(extents):
    print(f"data extent {i}: {s}..{e} ({e-s} bytes)")
if extents:
    print(f"last data byte ends at: {extents[-1][1]}")
else:
    print("no data extents (all hole)")
os.close(fd)
EOF"}
